func RawRecordLoadBody(r *TableReader, value *RawRecord) bool {
	RawRecordReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x211fcbbafe5331ab: // harness
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Harness, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x40c5f8104d76cc15: // execution
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Execution, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x0d3c21d222f73316: // source_schema
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.SourceSchema, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x05b096403aeadb34: // producer_version
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.ProducerVersion, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x4005570295afd25c: // billing
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Billing, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x93fab8f021712b13: // tokens
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.Tokens))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(TokenCountRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*TokenCountRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(TokenCountRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						TokenCountLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							TokenCountReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

