const UsageLoadRetainBuilder = "Usage: retention requires a region round trip through the VARIABLE form"
const UsageSaveRetainMessages = "Usage: retention requires a region round trip through the VARIABLE form"

func UsageLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Usage {
	return (*Usage)(tableRegionLoadRetain(region, wire, UsageTableType(), UsageTableType().NodeType, 2, report, retain))
}
func UsageMeasureRetain(value *Usage, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), UsageTableType(), nil, true, retain, nil, allocator...)
}
func UsageSaveRetain(value *Usage, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), UsageTableType(), buffer, false, retain, report, allocator...)
}
func UsageMeasureBodyRetain(value *Usage, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !UsageSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func UsageSaveBodyRetain(w *TableRetainWriter, value *Usage) bool {
	if !UsageSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
