func UsageLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, UsageTableType(), UsageTableType().NodeType, 2)
	return n
}
func UsageLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, UsageTableType(), UsageTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func UsageLoad(region, wire []byte, report *TableReport) *Usage {
	return (*Usage)(tableRegionLoad(region, wire, UsageTableType(), UsageTableType().NodeType, 2, report))
}
func UsageMeasure(value *Usage, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), UsageTableType(), nil, true, arena, allocator)
}
func UsageMeasureReason(value *Usage, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), UsageTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func UsageSave(value *Usage, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), UsageTableType(), buffer, false, arena, allocator)
}
func UsageLoadBuilder(b *UsageBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, UsageTableType(), UsageTableType().NodeType, 2, report)
}

// UsageReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func UsageReadStrict(wire []byte) (*Usage, error) {
	var b UsageBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := UsageLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type UsageBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *UsageBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Usage{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	UsageReset((*Usage)(p))
	return true
}
func (b *UsageBuilder) GetRoot() *Usage {
	if b.Arena.Locked {
		return nil
	}
	return (*Usage)(b.Arena.At(b.root))
}
func (b *UsageBuilder) AsConst() *Usage {
	if len(b.region) == 0 {
		return nil
	}
	return (*Usage)(unsafe.Pointer(&b.region[0]))
}
func (b *UsageBuilder) Region() []byte { return b.region }
func (b *UsageBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), UsageTableType(), &b.Arena)
}
func (b *UsageBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), UsageTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *UsageBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), UsageTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *UsageBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// TotalReset restores Total's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TotalReset(value *Total) {
	value.Records = 0
	TokensReset(&value.Tokens)
	value.WaitS = 0
	value.RunS = 0
	value.PredictedUsd = 0
	value.PredictedRecords = 0
	value.ActualUsd = 0
	value.ActualRecords = 0
	value.ActualBy = 0
	value.ChargedUsd = 0
	value.ChargedRecords = 0
}

func TotalMeasureBody(value *Total, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TotalSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TotalSaveBody(w *TableWriter, value *Total) bool {
	if !TotalSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
