const TotalLoadRetainBuilder = "Total: retention requires a region round trip through the VARIABLE form"
const TotalSaveRetainMessages = "Total: retention requires a region round trip through the VARIABLE form"

func TotalLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Total {
	return (*Total)(tableRegionLoadRetain(region, wire, TotalTableType(), TotalTableType().NodeType, 2, report, retain))
}
func TotalMeasureRetain(value *Total, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), TotalTableType(), nil, true, retain, nil, allocator...)
}
func TotalSaveRetain(value *Total, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), TotalTableType(), buffer, false, retain, report, allocator...)
}
func TotalMeasureBodyRetain(value *Total, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !TotalSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func TotalSaveBodyRetain(w *TableRetainWriter, value *Total) bool {
	if !TotalSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func TotalSaveBodyFieldsRetain(w *TableRetainWriter, value *Total) bool {
	{
		if value.Records != 0 {
			if ref := w.Ids.refAtHit(140, 0xa281d6f1b14296ed); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.Records))
		}
	}
	{
		mark := w.Ids.Count
		ref := w.Ids.refAtHit(128, 0x93fab8f021712b13)
		start := w.Ids.Count
		payload := TableRetainWriter{Measuring: true, Ids: w.Ids}
		{
			payload1 := payload.Ids.Path
			payload.Ids.Path = payload1.step(1, uint32(0))
			{
				mark := payload.Ids.Count
				n := TokensMeasureBodyRetain(&value.Tokens, payload.Ids)
				if n < 0 {
					return false
				}
				if !payload.putLebPair(uint64(n)) {
					payload.putLebWide(uint64(n))
				}
				if payload.Measuring {
					payload.Advance(n)
				} else {
					payload.Ids.Truncate(mark)
					if !TokensSaveBodyRetain(&payload, &value.Tokens) {
						return false
					}
				}
			}
			payload.Ids.Path = payload1
		}
		if payload.Overflow || w.Ids.Overflow {
			return false
		}
		if payload.Offset > 2 {
			if w.Measuring {
				w.Advance(tableLebBytes(ref) + 1 + payload.Offset)
			} else {
				w.Ids.Truncate(start)
				if !w.headerPair(ref, 13) {
					w.headerRest(ref, 13)
				}
				{
					payload2 := w.Ids.Path
					w.Ids.Path = payload2.step(1, uint32(0))
					{
						mark := w.Ids.Count
						n := TokensMeasureBodyRetain(&value.Tokens, w.Ids)
						if n < 0 {
							return false
						}
						if !w.putLebPair(uint64(n)) {
							w.putLebWide(uint64(n))
						}
						if w.Measuring {
							w.Advance(n)
						} else {
							w.Ids.Truncate(mark)
							if !TokensSaveBodyRetain(w, &value.Tokens) {
								return false
							}
						}
					}
					w.Ids.Path = payload2
				}
			}
		} else {
			w.Ids.Truncate(mark)
		}
	}
	{
		if value.WaitS != 0 {
			if ref := w.Ids.refAtHit(10, 0x0a9497e44dc2a65a); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.WaitS))
		}
	}
	{
		if value.RunS != 0 {
			if ref := w.Ids.refAtHit(102, 0x7901b96a32a658d4); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.RunS))
		}
	}
	{
		if value.PredictedUsd != 0 {
			if ref := w.Ids.refAtHit(125, 0x92a3a8e4efc77d34); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.PredictedUsd == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.PredictedUsd)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.PredictedRecords != 0 {
			if ref := w.Ids.refAtHit(201, 0xeedee011f3d42e4e); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.PredictedRecords))
		}
	}
	{
		if value.ActualUsd != 0 {
			if ref := w.Ids.refAtHit(85, 0x645f8e3e63296678); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.ActualUsd == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.ActualUsd)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.ActualRecords != 0 {
			if ref := w.Ids.refAtHit(58, 0x401e99160f2b88fa); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.ActualRecords))
		}
	}
	{
		if value.ActualBy != 0 {
			if ref := w.Ids.refAtHit(88, 0x6b049b4d3cff12b5); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.ActualBy == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.ActualBy)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.ChargedUsd != 0 {
			if ref := w.Ids.refAtHit(22, 0x1d61d03d5da3fd20); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.ChargedUsd == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.ChargedUsd)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.ChargedRecords != 0 {
			if ref := w.Ids.refAtHit(63, 0x47607fbb367ecfd2); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.ChargedRecords))
		}
	}
	if !tableRetainTail(w) {
		return false
	}
	return !w.Overflow && !w.Ids.Overflow
}

