const ConsumerLoadRetainBuilder = "Consumer: retention requires a region round trip through the VARIABLE form"
const ConsumerSaveRetainMessages = "Consumer: retention requires a region round trip through the VARIABLE form"

func ConsumerLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Consumer {
	return (*Consumer)(tableRegionLoadRetain(region, wire, ConsumerTableType(), ConsumerTableType().NodeType, 2, report, retain))
}
func ConsumerMeasureRetain(value *Consumer, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), ConsumerTableType(), nil, true, retain, nil, allocator...)
}
func ConsumerSaveRetain(value *Consumer, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), ConsumerTableType(), buffer, false, retain, report, allocator...)
}
func ConsumerMeasureBodyRetain(value *Consumer, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !ConsumerSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func ConsumerSaveBodyRetain(w *TableRetainWriter, value *Consumer) bool {
	if !ConsumerSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
