func ConsumerLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, ConsumerTableType(), ConsumerTableType().NodeType, 2)
	return n
}
func ConsumerLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, ConsumerTableType(), ConsumerTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func ConsumerLoad(region, wire []byte, report *TableReport) *Consumer {
	return (*Consumer)(tableRegionLoad(region, wire, ConsumerTableType(), ConsumerTableType().NodeType, 2, report))
}
func ConsumerMeasure(value *Consumer, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), ConsumerTableType(), nil, true, arena, allocator)
}
func ConsumerMeasureReason(value *Consumer, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), ConsumerTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func ConsumerSave(value *Consumer, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), ConsumerTableType(), buffer, false, arena, allocator)
}
func ConsumerLoadBuilder(b *ConsumerBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, ConsumerTableType(), ConsumerTableType().NodeType, 2, report)
}

// ConsumerReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ConsumerReadStrict(wire []byte) (*Consumer, error) {
	var b ConsumerBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ConsumerLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ConsumerBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ConsumerBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Consumer{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ConsumerReset((*Consumer)(p))
	return true
}
func (b *ConsumerBuilder) GetRoot() *Consumer {
	if b.Arena.Locked {
		return nil
	}
	return (*Consumer)(b.Arena.At(b.root))
}
func (b *ConsumerBuilder) AsConst() *Consumer {
	if len(b.region) == 0 {
		return nil
	}
	return (*Consumer)(unsafe.Pointer(&b.region[0]))
}
func (b *ConsumerBuilder) Region() []byte { return b.region }
func (b *ConsumerBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ConsumerTableType(), &b.Arena)
}
func (b *ConsumerBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ConsumerTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ConsumerBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ConsumerTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ConsumerBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// CardCostViewReset restores CardCostView's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CardCostViewReset(value *CardCostView) {
	value.Consumers = TableList[ConsumerRow]{}
	TotalReset(&value.Total)
	value.Cut = 0
	value.CarriedUsd = 0
	value.CarriedFrom = 0
	value.CarriedTo = 0
}

func CardCostViewMeasureBody(value *CardCostView, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !CardCostViewSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func CardCostViewSaveBody(w *TableWriter, value *CardCostView) bool {
	if !CardCostViewSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
