const NTableSaveRetainMessages = "NTable: retention requires a region round trip through the VARIABLE form"

func NTableLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *NTable {
	return (*NTable)(tableRegionLoadRetain(region, wire, NTableTableType(), NTableTableType().NodeType, 2, report, retain))
}
func NTableMeasureRetain(value *NTable, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), NTableTableType(), nil, true, retain, nil, allocator...)
}
func NTableSaveRetain(value *NTable, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), NTableTableType(), buffer, false, retain, report, allocator...)
}
func NTableMeasureBodyRetain(value *NTable, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !NTableSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func NTableSaveBodyRetain(w *TableRetainWriter, value *NTable) bool {
	if !NTableSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
