// BatchDeltaReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func BatchDeltaReadStrict(wire []byte) (*BatchDelta, error) {
	var b BatchDeltaBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := BatchDeltaLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type BatchDeltaBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *BatchDeltaBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(BatchDelta{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	BatchDeltaReset((*BatchDelta)(p))
	return true
}
func (b *BatchDeltaBuilder) GetRoot() *BatchDelta {
	if b.Arena.Locked {
		return nil
	}
	return (*BatchDelta)(b.Arena.At(b.root))
}
func (b *BatchDeltaBuilder) AsConst() *BatchDelta {
	if len(b.region) == 0 {
		return nil
	}
	return (*BatchDelta)(unsafe.Pointer(&b.region[0]))
}
func (b *BatchDeltaBuilder) Region() []byte { return b.region }
func (b *BatchDeltaBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), BatchDeltaTableType(), &b.Arena)
}
func (b *BatchDeltaBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), BatchDeltaTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *BatchDeltaBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), BatchDeltaTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *BatchDeltaBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
