// ReceiptReset restores Receipt's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReceiptReset(value *Receipt) {
	value.Id = 0
	value.Epoch = 0
	value.Before = 0
	value.After = 0
	value.Outcome = 0
	value.BatchDelta = 0
	value.Replay = false
}

func ReceiptMeasureBody(value *Receipt, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ReceiptSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ReceiptSaveBody(w *TableWriter, value *Receipt) bool {
	if !ReceiptSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
