// EpochSnapshotReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func EpochSnapshotReadStrict(wire []byte) (*EpochSnapshot, error) {
	var b EpochSnapshotBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := EpochSnapshotLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type EpochSnapshotBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *EpochSnapshotBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(EpochSnapshot{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	EpochSnapshotReset((*EpochSnapshot)(p))
	return true
}
func (b *EpochSnapshotBuilder) GetRoot() *EpochSnapshot {
	if b.Arena.Locked {
		return nil
	}
	return (*EpochSnapshot)(b.Arena.At(b.root))
}
func (b *EpochSnapshotBuilder) AsConst() *EpochSnapshot {
	if len(b.region) == 0 {
		return nil
	}
	return (*EpochSnapshot)(unsafe.Pointer(&b.region[0]))
}
