const LogSnapshotLoadRetainBuilder = "LogSnapshot: retention requires a region round trip through the VARIABLE form"
const LogSnapshotSaveRetainMessages = "LogSnapshot: retention requires a region round trip through the VARIABLE form"

func LogSnapshotLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *LogSnapshot {
	return (*LogSnapshot)(tableRegionLoadRetain(region, wire, LogSnapshotTableType(), LogSnapshotTableType().NodeType, 3, report, retain))
}
func LogSnapshotMeasureRetain(value *LogSnapshot, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), LogSnapshotTableType(), nil, true, retain, nil, allocator...)
}
func LogSnapshotSaveRetain(value *LogSnapshot, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), LogSnapshotTableType(), buffer, false, retain, report, allocator...)
}
