// LogSnapshotReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func LogSnapshotReadStrict(wire []byte) (*LogSnapshot, error) {
	var b LogSnapshotBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := LogSnapshotLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type LogSnapshotBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LogSnapshotBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LogSnapshot{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LogSnapshotReset((*LogSnapshot)(p))
	return true
}
func (b *LogSnapshotBuilder) GetRoot() *LogSnapshot {
	if b.Arena.Locked {
		return nil
	}
	return (*LogSnapshot)(b.Arena.At(b.root))
}
func (b *LogSnapshotBuilder) AsConst() *LogSnapshot {
	if len(b.region) == 0 {
		return nil
	}
	return (*LogSnapshot)(unsafe.Pointer(&b.region[0]))
}
func (b *LogSnapshotBuilder) Region() []byte { return b.region }
func (b *LogSnapshotBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LogSnapshotTableType(), &b.Arena)
}
func (b *LogSnapshotBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LogSnapshotTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LogSnapshotBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LogSnapshotTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LogSnapshotBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
