// MemDumpMemberReset restores MemDumpMember's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MemDumpMemberReset(value *MemDumpMember) {
	value.TableName = 0
	value.Member = 0
}

func MemDumpMemberMeasureBody(value *MemDumpMember, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !MemDumpMemberSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func MemDumpMemberSaveBody(w *TableWriter, value *MemDumpMember) bool {
	if !MemDumpMemberSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func MemDumpMemberSaveBodyFields(w *TableWriter, value *MemDumpMember) bool {
	{
		if value.TableName != 0 {
			if ref := w.Ids.refAtHit(90, 0x6bcb6e85b78cf363); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.TableName == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.TableName)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.Member != 0 {
			if ref := w.Ids.refAtHit(121, 0x8cada599d66ec543); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Member == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Member)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func MemDumpMemberLoadBody(r *TableReader, value *MemDumpMember) bool {
	MemDumpMemberReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x6bcb6e85b78cf363: // table_name
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.TableName, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x8cada599d66ec543: // member
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Member, index, 0x55fa23cd15155463, r.Report)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

