// MemDumpMemberReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func MemDumpMemberReadStrict(wire []byte) (*MemDumpMember, error) {
	var b MemDumpMemberBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := MemDumpMemberLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type MemDumpMemberBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *MemDumpMemberBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(MemDumpMember{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	MemDumpMemberReset((*MemDumpMember)(p))
	return true
}
func (b *MemDumpMemberBuilder) GetRoot() *MemDumpMember {
	if b.Arena.Locked {
		return nil
	}
	return (*MemDumpMember)(b.Arena.At(b.root))
}
func (b *MemDumpMemberBuilder) AsConst() *MemDumpMember {
	if len(b.region) == 0 {
		return nil
	}
	return (*MemDumpMember)(unsafe.Pointer(&b.region[0]))
}
func (b *MemDumpMemberBuilder) Region() []byte { return b.region }
func (b *MemDumpMemberBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), MemDumpMemberTableType(), &b.Arena)
}
func (b *MemDumpMemberBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), MemDumpMemberTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *MemDumpMemberBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), MemDumpMemberTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *MemDumpMemberBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// ---- THE FIXED FORM, form byte 3 (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's layout and then the values
// in declared order, every field at its declared storage width. The writer is
// constant-offset stores; the reader is ONE loop over ONE plan.

func TokensFixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	{
		es := src + 0
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.Input))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 8
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.CacheRead))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 16
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.CacheWrite))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 24
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.Output))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 32
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.Reasoning))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 40
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.Requests))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	{
		es := src + 48
		ed := dst + uint32(unsafe.Offsetof(Tokens{}.MaxPrompt))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	return n
}

func TokensFixedWriteBody(b []byte, value *Tokens) {
	tableFixedPut64(b[0:], uint64(value.Input))
	tableFixedPut64(b[8:], uint64(value.CacheRead))
	tableFixedPut64(b[16:], uint64(value.CacheWrite))
	tableFixedPut64(b[24:], uint64(value.Output))
	tableFixedPut64(b[32:], uint64(value.Reasoning))
	tableFixedPut64(b[40:], uint64(value.Requests))
	tableFixedPut64(b[48:], uint64(value.MaxPrompt))
}

